INSERT INTO locations (city_id, name, neighborhood, category, description, latitude, longitude, photo_url, vibe_difficulty, what_to_wear) VALUES

('11111111-0000-0000-0000-000000000002',
'Sloane Street',
'Chelsea',
'Luxury Retail',
'The most determinedly expensive street in Chelsea, running from Knightsbridge down to Sloane Square with Hermès, Chanel, Dolce & Gabbana and a Dior flagship in between. You are not necessarily shopping. You are moving between appointments. Everything is equidistant from your Chelsea home. Walk at a measured pace. Never look at prices.',
51.4964, -0.1607,
'https://images.unsplash.com/photo-1441986300917-64674bd600d8?w=800&q=80',
3,
'{"men": {"brands": ["Burberry", "Brunello Cucinelli", "Rolex", "Church''s"], "outfit": {"top": "A Burberry single-breasted trench coat over a clean merino rollneck in camel", "bottom": "Dark slim trousers or charcoal wool flannel", "shoes": "Church''s Shannon brogues in dark tan or polished black Oxfords", "bag": "Nothing, or a slim leather gloves-and-wallet situation", "accessories": "Rolex Datejust or Explorer, a quality umbrella carried closed (very Chelsea)"}, "color_palette": "Camel, charcoal, dark tan, navy — the full British luxury palette, no irony", "budget_dupe": "A good trench coat from Marks & Spencer or a secondhand Burberry from eBay, dark trousers from Cos, Church''s shoes are worth saving for. The trench is doing the entire job."}, "women": {"brands": ["Bottega Veneta", "Burberry", "Cartier", "LK Bennett"], "outfit": {"top": "Camel cashmere coat (this is the coat situation, nothing else will do) over a silk blouse", "bottom": "Tailored straight-leg trousers in camel or cream", "shoes": "Clean pointed kitten heel or classic slingback in nude", "bag": "Bottega Veneta Jodie or anything from their woven collection — or a Mulberry Bayswater for the Chelsea-specific energy", "accessories": "Cartier Love bracelet, silk scarf, sunglasses even in October"}, "color_palette": "Camel, ivory, nude, champagne — the full Chelsea housewife investment palette", "budget_dupe": "A camel coat from Cos is genuinely excellent. Mulberry bags hold their value and can be sourced secondhand. The pointed kitten heel from LK Bennett is the Chelsea acceptable budget option."}}'::jsonb),

('11111111-0000-0000-0000-000000000002',
'Duke of York Square Market (Saturdays)',
'Chelsea',
'Weekend Aristocrat',
'Every Saturday, this square behind the Saatchi Gallery becomes the most agreeable outdoor market in London. Artisan cheese, good bread, flowers sold by the stem. You are here because your Saturday begins with choosing the best sourdough, not because you need the sourdough. Carry a linen tote bag. Taste things freely and decisively.',
51.4924, -0.1619,
'https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=800&q=80',
2,
'{"men": {"brands": ["Barbour", "A.P.C.", "Apple Watch", "Sanders"], "outfit": {"top": "A waxed Barbour Beaufort jacket or a quilted gilet over a chunky rollneck or flannel shirt", "bottom": "Well-fitted dark jeans or cord trousers in olive or tobacco", "shoes": "Clean leather Chelsea boots or a good brogue boot", "bag": "A linen or canvas market tote — the most important prop here", "accessories": "Apple Watch or a simple field watch on canvas strap, a cashmere scarf in camel or grey"}, "color_palette": "Olive, tobacco, navy, oatmeal — country comes to Chelsea for the weekend", "budget_dupe": "A Barbour waxed jacket is an investment that lasts twenty years and never looks wrong in Chelsea. Source secondhand on eBay. Dark jeans from any brand are fine. The linen tote is £15 from a market stall — and is the point of the exercise."}, "women": {"brands": ["Barbour", "Toteme", "Cartier", "Penelope Chilvers"], "outfit": {"top": "Relaxed cashmere rollneck or a striped sailor top under a long olive quilted coat or Barbour", "bottom": "Well-fitted straight jeans or corduroys in a warm tone", "shoes": "Clean white trainers (Golden Goose if you''re committing) or leather ankle boots", "bag": "Woven straw basket or a quality linen tote — the Parisian market bag transplanted to Chelsea", "accessories": "A thick cashmere scarf, small gold hoops, Cartier Love bracelet visible below the sleeve"}, "color_palette": "Olive, oatmeal, ecru, burgundy — a Saturday that requires nothing from anyone", "budget_dupe": "Marks & Spencer does excellent knitwear for this exact look. White New Balance are a tenth of the Golden Goose price and read identically in market lighting. The basket tote can be found at any homeware shop for under £20 — and is literally the correct bag."}}'::jsonb),

('11111111-0000-0000-0000-000000000002',
'The Connaught Bar',
'Mayfair',
'Continental',
'Repeatedly voted one of the world''s best bars, the Connaught Bar serves a martini cart that comes to your table, prepared in front of you, by someone who has mastered the ritual. You are here for the martini and the room and the sense that you have, finally, reached the correct level. Dress as if you had dinner beforehand, even if you did not.',
51.5097, -0.1494,
'https://images.unsplash.com/photo-1543007630-9710e4a00a20?w=800&q=80',
5,
'{"men": {"brands": ["Huntsman", "Anderson & Sheppard", "Patek Philippe", "George Cleverley"], "outfit": {"top": "A proper Savile Row suit or at minimum a sharp navy single-breasted blazer with a tie", "bottom": "Matching trousers or dark grey flannels", "shoes": "Black cap-toe Oxfords, hand-lasted if you have them, mirror-polished always", "bag": "No bag. A man at the Connaught bar is not carrying anything other than his presence.", "accessories": "Patek Philippe or an AP Royal Oak, a real pocket square, no other jewelry"}, "color_palette": "Navy, charcoal, white — the most civilised palette in existence", "budget_dupe": "The Connaught will not turn you away for wearing a good M&S suit if it fits properly. Get it tailored. The shoes need to be polished. The attitude needs to be earned."}, "women": {"brands": ["Alexander McQueen", "Roland Mouret", "Van Cleef & Arpels", "Manolo Blahnik"], "outfit": {"top": "A structured cocktail dress or a tailored trouser suit — this is not a jeans situation", "bottom": "(dress) or matching tailored trousers", "shoes": "Pointed-toe heel in satin or leather — Manolo Blahnik is the correct answer but Jimmy Choo is permissible", "bag": "An evening clutch in satin or leather — small, structured, unencumbered", "accessories": "Van Cleef Alhambra or Cartier Panthère, drop earrings in gold or pearl, perfume you can afford"}, "color_palette": "Black, midnight blue, champagne — Mayfair evening, dressed for the occasion", "budget_dupe": "A beautifully cut black dress, sourced secondhand or from LK Bennett, will serve you well at the Connaught. Shoes: one real pair of elegant heels is a lifetime investment. Everything else can bend on budget — the shoes cannot."}}'::jsonb),

('11111111-0000-0000-0000-000000000002',
'Mount Street',
'Mayfair',
'Old Money',
'The quietest, most self-assured street in Mayfair. Marc Jacobs, Scott''s restaurant, the Connaught Hotel, Audley pub, and a sense of money so old it has forgotten it started somewhere. Walk it slowly. Look in windows without urgency. This is the opposite of Oxford Street in every possible way and that is entirely the point.',
51.5101, -0.1488,
'https://images.unsplash.com/photo-1560221328-12fe60f83ab8?w=800&q=80',
3,
'{"men": {"brands": ["Gieves & Hawkes", "Holland & Holland", "Rolex", "Tricker''s"], "outfit": {"top": "A well-cut Harris tweed sport coat or a Barbour over a fine merino", "bottom": "Cavalry twill or cord trousers in warm mid-brown or olive", "shoes": "Tricker''s Bourton brogues in tan or dark brown — the definitive Mount Street shoe", "bag": "Nothing, or a leather-handled umbrella as required", "accessories": "Rolex Explorer or vintage Omega, a plain woven tie if wearing a collar"}, "color_palette": "Harris tweed brown, olive, tan, mid-grey — old Mayfair money, pre-everything", "budget_dupe": "A good tweed jacket from a British charity shop is a legitimate find and an authentic piece. Tricker''s shoes are a real investment — source them from their own sale or secondhand. The Mount Street look is one of the most achievable because it''s genuinely old and therefore available."}, "women": {"brands": ["Mulberry", "Loro Piana", "Cartier", "L.K. Bennett"], "outfit": {"top": "Cashmere twinset in camel or pale grey, or a wool crepe blazer", "bottom": "A-line skirt in tweed or tartan at the knee, or tailored slim trousers in warm grey", "shoes": "Low block heel or court shoe in nude or tan", "bag": "Mulberry Bayswater in oak or black — the most Mayfair bag ever made", "accessories": "Pearl studs or small gold drops, a thin gold chain, a silk scarf knotted at the throat"}, "color_palette": "Camel, pearl grey, tartan — British heritage, worn with quiet conviction", "budget_dupe": "John Lewis does excellent cashmere twinsets seasonally. A Mulberry Bayswater from eBay, even worn, reads authentically. The shoes from Russell & Bromley are entirely appropriate here — not everything has to be from the designer floor."}}'::jsonb),

('11111111-0000-0000-0000-000000000002',
'The Wolseley',
'Piccadilly',
'Power Lunch',
'A grand Viennese-style café that was a car showroom in a previous life and is now the most civilised place to have breakfast, brunch, or lunch in London. You know you''ve made it when you can get a table at The Wolseley at 1pm on a Thursday. The eggs benedict is not the point. The room and the people in it are entirely the point.',
51.5073, -0.1419,
'https://images.unsplash.com/photo-1414235077428-338989a2e8c0?w=800&q=80',
3,
'{"men": {"brands": ["Ralph Lauren", "Pal Zileri", "Rolex", "Grenson"], "outfit": {"top": "Smart tailored blazer in charcoal or navy over a fine shirt — open collar or with a knitted tie", "bottom": "Well-pressed slim trousers in dark grey or navy", "shoes": "Grenson Fred triple-welt brogue or a clean leather Derby", "bag": "A slim leather portfolio or briefcase", "accessories": "Rolex or a quality dress watch, a clean pocket square if wearing a blazer"}, "color_palette": "Charcoal, navy, white — European business casual, intelligently assembled", "budget_dupe": "M&S Autograph tailoring hits this exactly. A good blazer from their formal range, well-fitted, with pressed trousers. The Wolseley is forgiving on the label if the silhouette is correct."}, "women": {"brands": ["Reiss", "Hobbs", "Cartier", "Russell & Bromley"], "outfit": {"top": "A silk blouse in a jewel tone or a fine-knit under a tailored jacket", "bottom": "Tailored slim trousers or a polished A-line skirt at the knee", "shoes": "Clean block heel or court shoe — nothing too fashion-forward, this is Piccadilly power breakfast", "bag": "A structured top-handle or polished leather tote", "accessories": "Gold chain, small pearl or gold earrings, a silk scarf for the Wolseley aesthetic"}, "color_palette": "Sapphire, burgundy, camel, cream — Central European elegance in a W1 context", "budget_dupe": "Reiss and Hobbs are the native brands of this aesthetic. Both hit the Wolseley look at the appropriate price point for the neighbourhood. Nobody at table 12 will ask."}}'::jsonb),

('11111111-0000-0000-0000-000000000002',
'Burlington Arcade',
'Mayfair',
'Luxury Retail',
'The 1819 covered arcade off Piccadilly is patrolled by Beadles in top hats who will ask you not to whistle, run, or carry an open umbrella. You will not do any of these things. You will stroll at a civilised pace, looking at cashmere, bespoke jewellery, and antique prints, considering whether to buy anything with the unhurried pleasure of someone who has considered all week and still has time.',
51.5096, -0.1397,
'https://images.unsplash.com/photo-1441986300917-64674bd600d8?w=800&q=80',
2,
'{"men": {"brands": ["N.Peal", "Deakin & Francis", "A. Lange & Söhne", "New & Lingwood"], "outfit": {"top": "A soft N.Peal cashmere in camel or mid-grey, or a fine merino rollneck", "bottom": "Dark slim cord or charcoal flannels", "shoes": "Polished Oxfords or suede loafers in dark tan — understated and quality", "bag": "A leather-handled paper shopping bag from something within the arcade, ideally", "accessories": "A vintage dress watch or A. Lange, a subtle signet ring, no other jewelry"}, "color_palette": "Camel, grey, dark tan — the Burlington Arcade palette is Edwardian England done correctly", "budget_dupe": "The arcade is the LARP, not the purchase. Enter confidently. Touch nothing unless invited. The experience is free. A good cashmere from Marks & Spencer worn properly reads as well as N.Peal in the arcade''s warm light."}, "women": {"brands": ["Asprey", "Annoushka", "Hermès", "N.Peal"], "outfit": {"top": "A fine cashmere twinset or a silk blouse in a traditional print", "bottom": "A tailored midi skirt in tweed or a slim trouser in warm grey", "shoes": "Flat pointed ballet pump or a modest block heel in classic tan or burgundy", "bag": "An Asprey or Mulberry — or any structured leather bag without modern branding", "accessories": "Pearl earrings, a gold chain, an heirloom ring if you have one"}, "color_palette": "Camel, pearl, burgundy, cream — the arcade has its own aesthetic gravity that pulls everything toward heritage", "budget_dupe": "The Burlington Arcade look is achievable from a quality British charity shop on a good day. Cashmere twinsets appear regularly. The shoes are the one investment point."}}'::jsonb),

('11111111-0000-0000-0000-000000000002',
'Fortnum & Mason',
'Piccadilly',
'Old Money',
'Founded in 1707, Fortnum & Mason sells hampers, preserves, tea, and the conviction that some institutions are worth maintaining exactly as they are. You are browsing as someone who sends hampers as a matter of course and receives them back. Taste the tea samples. Ask about the Champagne Vintage section as if you''re refilling the cellar.',
51.5074, -0.1387,
'https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=800&q=80',
2,
'{"men": {"brands": ["Barbour", "Brook Taverner", "Rolex", "Hunter"], "outfit": {"top": "Country-comes-to-town: a good hacking jacket or Barbour over a Tattersall check shirt", "bottom": "Cord or tweed trousers in mid-brown or tan", "shoes": "Well-worn tan brogue or chukka boot — Cheaney or a decent Loake", "bag": "A canvas-and-leather weekend bag or nothing", "accessories": "A flat cap or no hat, a quality umbrella, Rolex Explorer or vintage Omega"}, "color_palette": "Tan, tobacco, rust, cream — the colours of a country weekend in St. James''s", "budget_dupe": "Barbour is the investment (source secondhand). The rest: Tattersall shirt from any high street, cord trousers from M&S, Loake shoes from their outlet. Fortnum''s forgives everything except visible irony."}, "women": {"brands": ["Laura Ashley", "Boden", "Mulberry", "Hunter"], "outfit": {"top": "Printed silk blouse in florals or a Liberty print, or a fine-knit in rose pink", "bottom": "A midi skirt in a gentle print or straight-leg cord trousers in dusty rose or camel", "shoes": "Mary Jane block heel or low court shoe in tan", "bag": "A wicker basket or a Mulberry tote in tan — the Fortnum''s shopper bag is actually an acceptable prop", "accessories": "Pearl studs, a thin gold necklace, a head scarf if you''re feeling the full English country register"}, "color_palette": "Dusty rose, Liberty print, camel, ivory — Fortnum''s makes you want to live in a house with a garden and a long table", "budget_dupe": "The full Fortnum''s woman look can be sourced from Boden, John Lewis, and the occasional good charity shop. The key is the silhouette and the self-assurance. No brand is doing the work here — the posture of someone who sends hampers is."}}'::jsonb),

('11111111-0000-0000-0000-000000000002',
'The Ritz Hotel Palm Court',
'Piccadilly',
'Continental',
'Afternoon tea at The Ritz is a performance that has been running since 1906 and shows no sign of closing. Sittings are timed, dress code is enforced (jacket required for men), and the scones will arrive in a silver stand. You are not here for the scones. You are here for the feeling of existing in a room that is entirely unironic about its own luxury.',
51.5069, -0.1424,
'https://images.unsplash.com/photo-1566073771259-6a8506099945?w=800&q=80',
4,
'{"men": {"brands": ["Gieves & Hawkes", "Ede & Ravenscroft", "Patek Philippe", "John Lobb"], "outfit": {"top": "A blazer or suit jacket is literally required by The Ritz dress code. Navy blazer with brass buttons is the correct move. White shirt, tie or not.", "bottom": "Dark trousers — grey flannel is the ideal", "shoes": "Polished black or dark tan Oxfords, no loafers (borderline), certainly no boots", "bag": "Nothing at afternoon tea", "accessories": "A quality dress watch — Patek Philippe is correct but any clean dress watch reads well. A pocket square."}, "color_palette": "Navy, grey, white, gold — the Palm Court''s own colour scheme will coordinate with you whether you plan it or not", "budget_dupe": "M&S Autograph blazer pressed and matched with their flannel trousers is entirely correct. The Ritz enforces dress code, not brand code. Polish your shoes. That''s the real flex here."}, "women": {"brands": ["Chanel", "LK Bennett", "Cartier", "L''Wren Scott"], "outfit": {"top": "A day dress in a floral print or a classic suit in pastel — The Ritz has its own aesthetic gravity that pulls toward ladylike", "bottom": "(dress) or a suit skirt or tailored trouser in soft colour", "shoes": "Court shoe in nude or pastel — kitten heel is ideal", "bag": "A small structured bag in leather — something with a proper clasp", "accessories": "Pearl earrings or small gold drops, a delicate necklace, gloves if you''re fully committing (you should be)"}, "color_palette": "Blush, champagne, ivory, pale sage — The Palm Court''s gold-and-mirror interior wants soft colour to contrast with", "budget_dupe": "A beautiful vintage dress from a well-curated charity shop is more correct at The Ritz than fast fashion at full price. LK Bennett does the tailored dress and the court shoe in exactly the right register. Gloves from any department store."}}'::jsonb),

('11111111-0000-0000-0000-000000000002',
'Claridge''s Lobby Bar',
'Mayfair',
'Continental',
'The art deco lobby of Claridge''s has been the address of displaced monarchs, film stars, and quiet deals since 1898. The bar serves excellent cocktails in a room where the light is flattering and the conversation is conducted in low, serious tones. Order something with gin. Speak quietly. Sit in the armchairs near the fireplace.',
51.5126, -0.1488,
'https://images.unsplash.com/photo-1543007630-9710e4a00a20?w=800&q=80',
4,
'{"men": {"brands": ["Timothy Everest", "Brioni", "IWC", "Edward Green"], "outfit": {"top": "A sharp evening jacket or a very well-cut day suit in charcoal or navy, open collar acceptable for the bar", "bottom": "Matching suit trousers, pressed", "shoes": "Dark leather Oxfords or suede loafers in dark tan — Claridge''s is relaxed enough for suede", "bag": "Nothing — your coat is checked at the door anyway", "accessories": "IWC Portugieser or Jaeger-LeCoultre Reverso, a pocket square in silk, a signet ring"}, "color_palette": "Charcoal, dark navy, champagne gold — art deco with a pulse", "budget_dupe": "A dark, well-cut suit from SuitSupply worn with real leather shoes and a silk pocket square achieves the Claridge''s bar look completely. The room is intimate and warmly lit. Fabric matters less than proportion."}, "women": {"brands": ["Victoria Beckham", "Emilia Wickstead", "Bulgari", "Jimmy Choo"], "outfit": {"top": "A silk evening blouse in ivory or deep jewel tone, or a structured shift dress", "bottom": "(dress) or slim tailored trousers in black or midnight navy", "shoes": "A modest heel in satin or patent — this is a hotel bar, not a club", "bag": "A small evening bag or structured clutch, preferably in leather or satin", "accessories": "Bulgari Serpenti or any good gold bracelet, drop earrings, a delicate necklace"}, "color_palette": "Midnight navy, ivory, deep emerald, champagne — Claridge''s deco interior flatters jewel tones and understated luxury equally", "budget_dupe": "A silk blouse from & Other Stories (they do excellent evening silk at accessible prices) plus tailored trousers from Cos, a secondhand Bulgari-style cuff. The Claridge''s bar is dark enough that the craftsmanship of your shoes matters more than the label."}}'::jsonb),

('11111111-0000-0000-0000-000000000002',
'The Wallace Collection',
'Marylebone',
'Intellectual',
'A private art collection of staggering quality, free to enter, housed in a 19th-century townhouse in Marylebone. The Great Gallery contains more Fragonards, Rubens, and Velázquezs than many national museums. Arrive as someone who comes for the Sèvres porcelain first and the Frans Hals second. Carry a bag that could contain a notebook.',
51.5155, -0.1533,
'https://images.unsplash.com/photo-1560221328-12fe60f83ab8?w=800&q=80',
2,
'{"men": {"brands": ["Drake''s", "Margaret Howell", "Nomos Glashütte", "Grenson"], "outfit": {"top": "A soft unstructured blazer in earth tones over a fine-stripe Oxford shirt or a moleskin in mid-green", "bottom": "Slim cord trousers in tobacco or dark olive", "shoes": "Suede desert boot or a good leather chukka", "bag": "A leather satchel or proper book bag — something with wear on it", "accessories": "Nomos Tangente or a vintage dress watch, round wire-rimmed glasses"}, "color_palette": "Tobacco, dark olive, rust, camel — the colours of a room of Dutch Golden Age paintings", "budget_dupe": "The Wallace Collection LARP is entirely achievable from Marks & Spencer and a good charity shop. The look is worn-in intellectual, not purchased-this-season. An older corduroy blazer is better than a new one here."}, "women": {"brands": ["Margaret Howell", "Toast", "Hermès", "Penelope Chilvers"], "outfit": {"top": "A fine-knit turtleneck in rust or sage, or a velvet blazer in dusty plum", "bottom": "A midi A-line skirt in a muted print or straight wool trousers", "shoes": "Leather ankle boot or flat loafer with a good leather sole", "bag": "A worn leather tote or a bucket bag in cognac — something that looks like it''s been to galleries before", "accessories": "A simple silk scarf, gold hoop earrings, a stack of thin rings"}, "color_palette": "Rust, sage, dusty plum, cognac — the Wallace Collection''s interiors suggest the colour palette, and they''re right", "budget_dupe": "Toast and Margaret Howell sale items are specifically designed for this audience. The charity shops near Marylebone High Street have excellent pickings. The look requires texture and earth tones, which are the cheapest things to buy well."}}'::jsonb),

('11111111-0000-0000-0000-000000000002',
'Chiltern Firehouse Bar',
'Marylebone',
'Art World',
'André Balazs''s conversion of a Victorian fire station is the most reliable celebrity-spotting location in London and the most committed art-world-adjacent bar in Marylebone. The entrance is nonchalant. The interior is extraordinary. Getting a reservation requires either very good timing or knowing someone. Having a drink at the bar requires only confidence.',
51.5212, -0.1579,
'https://images.unsplash.com/photo-1543007630-9710e4a00a20?w=800&q=80',
5,
'{"men": {"brands": ["Saint Laurent", "Acne Studios", "AP", "Common Projects"], "outfit": {"top": "Black Saint Laurent or Acne Studios leather jacket over a plain white tee, or a silk shirt in deep burgundy open four buttons", "bottom": "Black slim jeans or dark charcoal slim trousers", "shoes": "Black leather Chelsea boot or white Common Projects — nothing in between", "bag": "Nothing or a small black leather clutch-wallet", "accessories": "AP Royal Oak or Rolex Submariner, one piece of Chrome Hearts, sunglasses inside always"}, "color_palette": "Black, white, deep burgundy — Chiltern is not a neutral place, dress accordingly", "budget_dupe": "All-black from any brand done with total confidence is the Chiltern LARP. The jacket matters: source a secondhand leather jacket that fits impeccably. One good leather jacket beats any amount of designer basics."}, "women": {"brands": ["Bottega Veneta", "Jacquemus", "Cartier", "Charlotte Tilbury"], "outfit": {"top": "A satin slip dress or a structured blazer with nothing underneath — both read correctly here", "bottom": "(dress) or leather trousers or a sharp mini skirt", "shoes": "A barely-there heeled sandal or a pointed ankle boot in black or cognac", "bag": "Bottega Veneta Jodie or Loewe Puzzle — something that signals taste without spelling it out", "accessories": "A stack of thin gold bracelets, small hoops, the right perfume (Byredo or Le Labo is correct for Chiltern)"}, "color_palette": "Black, ivory, cognac, deep emerald — the palette of someone who''s been on four guest lists tonight and will be on none tomorrow", "budget_dupe": "A satin slip dress from Reformation or & Other Stories gets you there. The bag is the critical investment — source it secondhand. Chiltern rewards confidence over completeness."}}'::jsonb),

('11111111-0000-0000-0000-000000000002',
'Harvey Nichols',
'Knightsbridge',
'Luxury Retail',
'The department store that has always tried harder than Harrods and been right to. The fifth-floor restaurant and bar is a destination in itself; the beauty hall is one of the best in the world. You are here on a weekday, not a weekend, because that is when the serious people shop. Browse deliberately. Ask questions with the confidence of someone who already knows the answer.',
51.5024, -0.1602,
'https://images.unsplash.com/photo-1441986300917-64674bd600d8?w=800&q=80',
3,
'{"men": {"brands": ["Zegna", "Canali", "Rolex", "Loake"], "outfit": {"top": "A slim-cut cashmere sport coat or a lightweight suit jacket, shirt tucked, no tie", "bottom": "Dark slim trousers or dark jeans on the more casual floors", "shoes": "Clean suede loafers or polished leather Derby", "bag": "A Harvey Nichols bag (meta) or a slim leather portfolio", "accessories": "A clean dress watch, minimal jewelry, sunglasses in hand"}, "color_palette": "Navy, camel, black — shopping has a dress code and Harvey Nichols enforces it by proximity", "budget_dupe": "Harvey Nichols sale buys real brand pieces at occasionally reasonable prices. The LARP move is to carry a Harvey Nichols carrier bag (free, from a previous visit or a £5 candle) while wearing anything."}, "women": {"brands": ["Stella McCartney", "Self-Portrait", "Cartier", "Gianvito Rossi"], "outfit": {"top": "A Self-Portrait dress or a well-cut blazer over a silk cami in cream or soft pink", "bottom": "(dress) or tailored trousers", "shoes": "A pointed-toe heel or clean mule in nude or black — Gianvito Rossi if possible", "bag": "Something structured, mid-size, in a quality leather — the Harvey Nichols shopper in one hand is entirely acceptable", "accessories": "Cartier or Bulgari bracelet, small gold earrings"}, "color_palette": "Soft pink, cream, black — Knightsbridge daywear has its own code and Harvey Nichols is its temple", "budget_dupe": "Self-Portrait does occasion dressing at accessible designer prices. A well-cut blazer from Reiss, a decent heel from Kurt Geiger (Knightsbridge''s accepted compromise brand), and a quality bag from the sale rail."}}'::jsonb),

('11111111-0000-0000-0000-000000000002',
'Bluebird Chelsea',
'King''s Road',
'Weekend Aristocrat',
'The old Bluebird Garage on King''s Road is now a restaurant that catches the full Chelsea Saturday energy: people who live nearby and are spending the day exactly as they intend. The outdoor terrace is the goal. Brunch, a Bloody Mary, no phones on the table, and the sense of a life very much under control.',
51.4878, -0.1669,
'https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=800&q=80',
3,
'{"men": {"brands": ["Polo Ralph Lauren", "Orlebar Brown", "Rolex", "Veja"], "outfit": {"top": "A linen shirt in pale blue or white, untucked, or a fine-stripe Breton in navy", "bottom": "Clean chino in stone or mid-blue, well-fitted", "shoes": "Clean white trainers or tan leather loafers", "bag": "A canvas tote or small rucksack", "accessories": "Rolex Datejust or clean Apple Watch, sunglasses, no tie or formal elements"}, "color_palette": "Stone, pale blue, navy, white — Chelsea Saturday in a sunlit month", "budget_dupe": "Gap or Uniqlo linen shirt, Uniqlo slim chino, clean white New Balance. The Bluebird terrace is forgiving — the sunlight and the Bloody Mary do the rest."}, "women": {"brands": ["Rixo", "Zimmermann", "Cartier", "Ancient Greek Sandals"], "outfit": {"top": "A floral printed midi dress or an effortless linen co-ord in sage or dusty blue", "bottom": "(dress) or linen wide-leg trousers with a simple cami", "shoes": "Ancient Greek Sandals or a simple leather sandal in tan, or white trainers if it''s October", "bag": "A wicker bag or linen tote for the terrace aesthetic, or a leather crossbody", "accessories": "Gold jewellery, oversized sunglasses, a hat if sunny"}, "color_palette": "Floral, sage, dusty blue, linen — King''s Road weekend in the right season", "budget_dupe": "Rixo and Zimmermann are the target — source their pieces on eBay or Vestiaire Collective. Ancient Greek Sandals have a budget equivalent in almost every high street shop. The floral dress is the key piece; invest there."}}'::jsonb),

('11111111-0000-0000-0000-000000000002',
'Annabel''s',
'Mayfair',
'Art World',
'The most storied private members'' club in London, open to non-members for dinner if you can get a reservation. The interior redesign by Martin Brudnizki is one of the great maximalist rooms: floor-to-ceiling tropical murals, jewel-toned velvet, flowers everywhere. Dress with the conviction of someone who has been a member since before the redesign and is generously amused by it.',
51.5097, -0.1475,
'https://images.unsplash.com/photo-1543007630-9710e4a00a20?w=800&q=80',
5,
'{"men": {"brands": ["Valentino", "Tom Ford", "Patek Philippe", "Christian Louboutin"], "outfit": {"top": "A velvet dinner jacket in midnight blue or a perfectly cut black suit — Annabel''s rewards maximalism within the bounds of elegance", "bottom": "Matching trousers, slim, no break", "shoes": "Patent leather Oxfords or velvet loafers (the latter is very Annabel''s)", "bag": "Nothing — you have pockets or you have a problem", "accessories": "Patek Philippe, a boutonnière if feeling theatrical, no tie required but a statement watch is"}, "color_palette": "Midnight blue, emerald, black velvet — Annabel''s interior will try to outdo you; do not let it", "budget_dupe": "A velvet dinner jacket can be found on eBay for very little — it''s not a common secondhand item so supply is good and prices are low. The look is in the jacket, not the brand. Polish everything else."}, "women": {"brands": ["Valentino", "Giambattista Valli", "Bulgari", "Alexandre Vauthier"], "outfit": {"top": "A ball-gown silhouette or a statement cocktail dress in a maximalist print or rich colour — Annabel''s is the one place where more is genuinely more", "bottom": "(dress)", "shoes": "A high heel in gold, satin, or jewelled — this is not the night for kitten heels", "bag": "A jewelled minaudière or satin clutch — something that catches light", "accessories": "Go bold: Bulgari, chandelier earrings, a cuff bracelet — Annabel''s interiors justify jewellery that would be too much anywhere else"}, "color_palette": "Emerald, sapphire, ruby, gold — the Annabel''s palette is their own maximalist tropical mural and you should try to compete", "budget_dupe": "A vintage ball gown from a specialist vintage shop or Vestiaire is the best option here — the period look fits the room perfectly. A theatrical secondhand piece beats a budget-brand cocktail dress completely at Annabel''s."}}'::jsonb),

('11111111-0000-0000-0000-000000000002',
'The Savoy American Bar',
'Strand',
'Continental',
'The American Bar at The Savoy has been serving cocktails since 1893 and is the birthplace of the Hanky Panky and the Between the Sheets. Harry Craddock''s ghost approves of everyone who orders properly. You will order properly. You are seated in a leather armchair. You have just come from somewhere and are going somewhere else. The bar is the pause between.',
51.5102, -0.1213,
'https://images.unsplash.com/photo-1543007630-9710e4a00a20?w=800&q=80',
4,
'{"men": {"brands": ["Chester Barrie", "Brioni", "Cartier", "Carmina"], "outfit": {"top": "A dark suit in navy or charcoal, white shirt, no tie or a knitted silk tie", "bottom": "Matching suit trousers", "shoes": "Dark Oxford or suede loafer in dark tan", "bag": "Nothing", "accessories": "Cartier Santos or vintage Omega, pocket square in white linen"}, "color_palette": "Navy, charcoal, white, dark tan — the American Bar has been dressing its clientele in the same palette for 130 years", "budget_dupe": "A dark navy suit from SuitSupply, properly tailored, with a white shirt and polished leather shoes. The Savoy American Bar is about the ritual, not the labels. Order correctly — that''s the most important thing."}, "women": {"brands": ["Jenny Packham", "Ghost", "Van Cleef & Arpels", "Aquazzura"], "outfit": {"top": "A 1930s-inspired bias-cut silk dress or a sleek tailored suit — the Savoy''s art deco interior suggests decade-appropriate glamour", "bottom": "(dress) or wide-leg palazzo trousers with a satin blouse", "shoes": "T-bar or strappy heel in gold or black satin", "bag": "A satin or beaded evening clutch", "accessories": "Art deco-inspired jewelry: geometric pieces in gold and stones, a bracelet stack, drop earrings"}, "color_palette": "Champagne, black, deep cobalt, ivory — art deco glamour, worn without self-consciousness", "budget_dupe": "A 1930s-inspired bias-cut dress from a good vintage shop costs almost nothing and is arguably more correct at the Savoy American Bar than a modern designer piece. The art deco jewelry aesthetic is well-served by costume jewelry of quality — Miriam Haskell pieces on eBay are affordable and extraordinary."}}'::jsonb);

